                "8": "{1}{2}{3}{4}{7}{8}{10}{12}{14}{17}",
                "9": "{1}{2}{3}{4}{7}{8}{10}{12}{14}{16}",
                "10": "{1}{2}{3}{4}{7}{8}{11}{12}{14}{17}",
                "11": "{1}{2}{3}{4}{7}{8}{11}{12}{14}{16}",
                "12": "{1}{2}{3}{4}{5}{6}{9}{13}{15}{17}",
